// Race evaluation between guessed race and secret target race
function evaluateRaceGuess(guess, target) {
  const isWin = Boolean(
    (guess.id && target.id && guess.id === target.id) ||
    (guess.name && target.name && guess.name.trim().toLowerCase() === target.name.trim().toLowerCase())
  );

  // 1. Grade (G1, G2, G3, OP)
  // Green if exact, Yellow if +-1 grade, with Arrow ⬆️ / ⬇️
  let gradeStatus = "mismatch";
  const gradeDiff = Math.abs(guess.grade_num - target.grade_num);
  if (gradeDiff === 0) {
    gradeStatus = "exact";
  } else if (gradeDiff === 1) {
    gradeStatus = "partial";
  }
  let gradeArrow = "";
  if (target.grade_num < guess.grade_num) gradeArrow = "⬆️";
  else if (target.grade_num > guess.grade_num) gradeArrow = "⬇️";

  // 2. Racetrack
  let trackStatus = "mismatch";
  if (guess.track_id === target.track_id) {
    trackStatus = "exact";
  } else if (guess.region === target.region) {
    trackStatus = "partial"; // Same geographic region (e.g. Hokkaido: Sapporo & Hakodate)
  }

  // 3. Distance Length in meters
  let distStatus = "mismatch";
  const distDiff = Math.abs(guess.length - target.length);
  if (distDiff === 0) {
    distStatus = "exact";
  } else if (distDiff <= 200) {
    distStatus = "partial";
  }
  let distArrow = "";
  if (target.length > guess.length) distArrow = "⬆️";
  else if (target.length < guess.length) distArrow = "⬇️";

  // 4. Distance Type (Short, Mile, Medium, Long) - NO YELLOW
  let distTypeStatus = (guess.division === target.division) ? "exact" : "mismatch";

  // 5. Surface / Terrain (Turf vs Dirt)
  let terrainStatus = (guess.terrain === target.terrain) ? "exact" : "mismatch";

  // 6. Turn (Late December, Early May, etc. - 24 half-month turns per calendar year)
  let turnStatus = "mismatch";
  const turnDiff = Math.abs(guess.turn_index - target.turn_index);
  const circDiff = Math.min(turnDiff, 24 - turnDiff);
  if (turnDiff === 0) {
    turnStatus = "exact";
  } else if (circDiff <= 2) {
    turnStatus = "partial"; // within 1 month (±2 turns)
  }
  let turnArrow = "";
  if (target.turn_index > guess.turn_index) turnArrow = "⬆️";
  else if (target.turn_index < guess.turn_index) turnArrow = "⬇️";

  // 7. Late Race Start Location (C2, C3, C4, Backstretch, Homestretch)
  let lateRaceStatus = "mismatch";
  const isCorner = loc => loc.startsWith("C");
  const isStraight = loc => ["Backstretch", "Homestretch"].includes(loc);

  if (guess.late_race === target.late_race) {
    lateRaceStatus = "exact";
  } else if (
    (isCorner(guess.late_race) && isCorner(target.late_race)) ||
    (isStraight(guess.late_race) && isStraight(target.late_race))
  ) {
    lateRaceStatus = "partial";
  }

  // 8. Fan Gain (Base 1st-place fan gain)
  let fansStatus = "mismatch";
  const targetFans = target.fans || 0;
  const guessFans = guess.fans || 0;
  const fansDiff = targetFans - guessFans;
  const absFansDiff = Math.abs(fansDiff);
  if (absFansDiff === 0) {
    fansStatus = "exact";
  } else if (absFansDiff <= 2000) {
    fansStatus = "partial"; // within ±2,000 fans
  }
  let fansArrow = "";
  if (targetFans > guessFans) fansArrow = "⬆️";
  else if (targetFans < guessFans) fansArrow = "⬇️";

  return {
    isWin,
    guess,
    target,
    results: {
      grade: { val: guess.grade, arrow: gradeArrow, status: gradeStatus, diff: target.grade_num - guess.grade_num },
      track: { val: guess.track_name, status: trackStatus },
      distance: { val: `${guess.length}m`, arrow: distArrow, status: distStatus, diff: target.length - guess.length },
      distance_type: { val: guess.division, status: distTypeStatus },
      terrain: { val: guess.terrain, status: terrainStatus },
      turn: { val: guess.turn, arrow: turnArrow, status: turnStatus, diff: target.turn_index - guess.turn_index },
      season: { val: guess.season, status: (guess.season === target.season ? "exact" : "mismatch") },
      late_race: { val: guess.late_race, status: lateRaceStatus },
      fans: { val: `${guessFans.toLocaleString()}`, arrow: fansArrow, status: fansStatus, diff: fansDiff }
    }
  };
}

// Daily race deterministic selector (picks from graded G1, G2, G3 races)
function getDailyRace(dateString) {
  if (!dateString) dateString = new Date().toISOString().slice(0, 10);
  const gradedPool = ALL_RACES.filter(r => r.grade_num <= 3); // G1, G2, G3
  let hash = 0;
  for (let i = 0; i < dateString.length; i++) {
    hash = (hash * 41 + dateString.charCodeAt(i)) & 0x7fffffff;
  }
  const index = hash % gradedPool.length;
  return gradedPool[index];
}

window.ALL_RACES = ALL_RACES;
window.evaluateRaceGuess = evaluateRaceGuess;
window.getDailyRace = getDailyRace;
